  'demo.tour.ui.finish': 'پایان',
  'demo.tour.ui.close': 'پایان تور',
  'demo.tour.ui.clickHint': 'برای ادامه روی بخش برجسته‌شده کلیک کن.',
  'demo.tour.ui.missing': 'آن بخش از صفحه الان دیده نمی‌شود. با «بعدی» ادامه بده — در این فاصله محصول کاملاً در اختیار توست.',
  'demo.tour.ui.endTitle': 'این خود محصول بود',
