  'trialMail.approved.subject': "نسخهٔ آزمایشی Curahold برای {company} آماده است",
  'trialMail.approved.body': "سلام {name}،\n\nخبر خوب: نسخهٔ آزمایشی Curahold برای {company} آماده است. برای {seats} نفر جا دارد و تا {until} فعال است.\n\nبا این پیوند وارد شوید تا شرکتتان را راه‌اندازی کنید. پیوند یک بار و به مدت ۷ روز کار می‌کند:\n\n{link}\n\nپس از ورود، برنامهٔ راه‌اندازی گام‌به‌گام شما را برای دعوت تیم و اتصال ابزارها راهنمایی می‌کند. اگر پرسشی دارید، کافی است به همین ایمیل پاسخ دهید.\n\nتیم Curahold",
  'trialMail.rejected.subject': "دربارهٔ درخواست نسخهٔ آزمایشی Curahold برای {company}",
  'trialMail.rejected.body': "سلام {name}،\n\nاز علاقهٔ شما به Curahold و وقتی که برای معرفی {company} گذاشتید سپاسگزاریم.\n\nدر حال حاضر نمی‌توانیم برای این درخواست نسخهٔ آزمایشی باز کنیم. این قضاوتی دربارهٔ تیم شما نیست: نسخه‌های آزمایشی را گام‌به‌گام باز می‌کنیم تا هر شرکت از روز اول پشتیبانی درستی داشته باشد.\n\nاطلاعات شما را نگه می‌داریم و هر وقت بتوانیم نسخهٔ آزمایشی مناسبی پیشنهاد کنیم، با شما تماس می‌گیریم. اگر چیزی در طرف شما تغییر کرد، کافی است به همین ایمیل پاسخ دهید.\n\nبا احترام،\nتیم Curahold",
