  'fin.what.finfile': "Logo، Mikro، Tally، SAP Business One یا هر برنامهٔ دیگر: خروجی Excel یا CSV را بارگذاری کنید.",
  'fin.steps.zohobooks': "با حساب Zoho که سازمان شما در Zoho Books را می‌بیند وارد شوید.\nبه Curahold اجازه دهید مخاطبان، فاکتورها و پرداخت‌ها را بخواند. فقط اجازهٔ خواندن می‌خواهد.\nپس از بازگشت به اینجا، اولین خواندن را شروع کنید و مشتریانی را که تطبیق داده نشدند بررسی کنید.",
  'fin.steps.xero': "وارد Xero شوید و سازمانی را که می‌خواهید وصل کنید انتخاب کنید.\nاجازهٔ خواندن مخاطبان و تراکنش‌ها را بدهید؛ Curahold نمی‌تواند چیزی را در Xero تغییر دهد.\nپس از بازگشت به اینجا، اولین خواندن را شروع کنید و مشتریانی را که تطبیق داده نشدند بررسی کنید.",
  'fin.steps.freee': "وارد freee شوید و شرکت (事業所) مورد نظر را انتخاب کنید.\nاجازهٔ دسترسی بدهید؛ Curahold فقط طرف‌حساب‌ها و معاملات فروش را می‌خواند.\nپس از بازگشت به اینجا، اولین خواندن را شروع کنید و مشتریانی را که تطبیق داده نشدند بررسی کنید.",
  'fin.steps.quickbooks': "وارد Intuit شوید و شرکت QuickBooks مورد نظر را انتخاب کنید.\nاجازهٔ دسترسی به داده‌های حسابداری را بدهید؛ Curahold فقط مشتریان، فاکتورها و پرداخت‌ها را می‌خواند.\nپس از بازگشت به اینجا، اولین خواندن را شروع کنید و مشتریانی را که تطبیق داده نشدند بررسی کنید.",
  'fin.steps.odoo': "در Odoo، پروفایل خود ← ترجیحات ← امنیت حساب را باز کنید و یک کلید API بسازید.\nنشانی Odoo و نام کاربری خود را یادداشت کنید. در Odoo.sh یا سرور خودتان، نام پایگاه داده را هم.\nآن‌ها را در زیر وارد کنید. در Odoo Online، دسترسی API به طرح Custom نیاز دارد (قانون Odoo).",
  'fin.steps.parasut': "از پشتیبانی Paraşüt دسترسی API برای شرکتتان بخواهید؛ آن‌ها یک client ID و client secret می‌فرستند.\nشمارهٔ شرکت شما در نوار نشانی پس از uygulama.parasut.com/ است.\nآن‌ها را با ایمیل و رمز یک کاربر Paraşüt وارد کنید. رمز فقط یک بار برای گرفتن کلید به کار می‌رود و ذخیره نمی‌شود.",
  'fin.steps.finfile': "مشتریان، فاکتورها و پرداخت‌ها را از برنامهٔ خود به‌صورت Excel یا CSV خروجی بگیرید.\nآن‌ها را در ستون‌های الگو قرار دهید؛ الگو را در صفحهٔ بعد می‌توانید دانلود کنید.\nاول مشتریان، بعد فاکتورها و سپس پرداخت‌ها را بارگذاری کنید. هر وقت ارقام تازه‌تر خواستید، فایل جدیدی بارگذاری کنید.",
  'support.field.odoo.url': "نشانی Odoo",
